#!/usr/bin/env python3
"""Send keystrokes / commands to the QEMU monitor socket (/tmp/qemu-monitor.sock)."""
import socket, sys, time

SOCK = "/tmp/qemu-monitor.sock"
MAP = {' ':'spc','\n':'ret','\t':'tab','-':'minus','=':'equal','[':'bracket_left',
       ']':'bracket_right',';':'semicolon',"'":'apostrophe','`':'grave_accent',
       ',':'comma','.':'dot','/':'slash','\\':'backslash'}
SHIFT = {':':'semicolon','_':'minus','+':'equal','"':'apostrophe','<':'comma','>':'dot',
         '?':'slash','|':'backslash','{':'bracket_left','}':'bracket_right','~':'grave_accent',
         '!':'1','@':'2','#':'3','$':'4','%':'5','^':'6','&':'7','*':'8','(':'9',')':'0'}

def mon(cmds, delay=0.05):
    s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM); s.settimeout(5); s.connect(SOCK)
    time.sleep(0.2)
    try: s.recv(65536)
    except Exception: pass
    out = b''
    for c in cmds:
        s.sendall((c + '\n').encode())
        time.sleep(delay)
        try: out += s.recv(65536)
        except Exception: pass
    s.close()
    return out.decode('utf-8', 'replace')

def keys_for(text):
    ks = []
    for ch in text:
        if ch in MAP: ks.append(MAP[ch])
        elif ch in SHIFT: ks.append('shift-' + SHIFT[ch])
        elif ch.isupper(): ks.append('shift-' + ch.lower())
        else: ks.append(ch)
    return ks

def type_text(text, delay=0.08):
    mon(['sendkey ' + k for k in keys_for(text)], delay)

if __name__ == '__main__':
    if sys.argv[1] == 'type': type_text(sys.argv[2])
    elif sys.argv[1] == 'key': mon(['sendkey ' + k for k in sys.argv[2:]], 0.15)
    else: print(mon(sys.argv[1:]))
PY
