#!/usr/bin/env python3
"""Grab the QEMU guest screen via the monitor socket.

Usage: screen.py [out.png]   -> prints "WIDTHxHEIGHT ncolors"
"""
import os
import sys
import time

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from qkey import mon  # noqa: E402


def grab(png=None):
    ppm = '/tmp/.screen.ppm'
    try:
        os.unlink(ppm)
    except OSError:
        pass
    mon(['screendump %s' % ppm], delay=0.3)
    for _ in range(20):
        if os.path.exists(ppm) and os.path.getsize(ppm) > 0:
            break
        time.sleep(0.25)
    from PIL import Image
    im = Image.open(ppm)
    im.load()
    if png:
        im.save(png)
    return im.size, len(im.getcolors(1 << 20) or [])


if __name__ == '__main__':
    size, ncol = grab(sys.argv[1] if len(sys.argv) > 1 else None)
    print('%dx%d %d' % (size[0], size[1], ncol))

#!/bin/bash
# noVNC web interface: nginx on port 80 -> websockify (6080) -> QEMU VNC (5901)
set -eu

cat > /etc/nginx/sites-available/novnc <<'EOF'
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;

    root /usr/share/novnc;
    index vnc.html;

    location / {
        try_files $uri $uri/ /vnc.html;
    }

    # noVNC's default websocket path
    location /websockify {
        proxy_pass http://127.0.0.1:6080/;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 86400s;
        proxy_send_timeout 86400s;
        proxy_buffering off;
    }
}
EOF

ln -sf /etc/nginx/sites-available/novnc /etc/nginx/sites-enabled/novnc
rm -f /etc/nginx/sites-enabled/default

# websockify bridge: TCP 6080 (HTTP/WS) -> VNC 5901
pkill -f 'websockify.*6080' 2>/dev/null || true
sleep 1
websockify --daemon --web /usr/share/novnc 6080 127.0.0.1:5901

nginx -t
if pgrep -x nginx >/dev/null; then nginx -s reload; else nginx; fi
sleep 1
ss -ltn | grep -E ':(80|5901|6080) ' || true

